test("CAT-284: short pages from deleted rows do not end the scan", () => {
  const rows = [{id:"i-1",name:"A"},{id:"i-2",name:"B",deleted:true},{id:"i-3",name:"C"}];
  for (const collection of ["invoices","projects"]) {
    const gateway = new MemoryGateway({ [collection]: rows });
    assert.deepEqual(exportCatalog(gateway, collection, {pageSize:2}).entries.map(r=>r.id), ["i-1","i-3"]);
    assert.ok(gateway.requests.every(r => r.limit === 2));
  }
});
EOF
